# envcfg.py
import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        with open(toml_path, 'rb') as f:
            toml_config = tomllib.load(f)
            config.update(tomllib_config)
    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            nested_keys = key[len(env_prefix)+1:].split('__')
            current = config
            for k in nested_keys[:-1]:
                if k not in current:
                    current[k] = {}
                current = current[k]
            current[nested_keys[-1]] = _coerce(value, defaults.get(nested_keys[-1]))
    return config

def _coerce(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ('true', '1', 'yes')
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for {value}')

# test_envcfg.py
import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'key': 'value'}
    assert load_config(defaults) == {'key': 'value'}

def test_toml():
    with open('config.toml', 'wb') as f:
        f.write(b'key = "toml_value"')
    assert load_config({}, 'config.toml') == {'key': 'toml_value'}

def test_env():
    os.environ['APP__KEY'] = 'env_value'
    assert load_config({}, env_prefix='APP') == {'key': 'env_value'}

def test_precedence():
    with open('config.toml', 'wb') as f:
        f.write(b'key = "toml_value"')
    os.environ['APP__KEY'] = 'env_value'
    assert load_config({'key': 'default_value'}, 'config.toml', env_prefix='APP') == {'key': 'env_value'}

def test_coercion():
    os.environ['APP__KEY'] = '1'
    assert load_config({'key': 0}, env_prefix='APP') == {'key': 1}

def test_error():
    os.environ['APP__KEY'] = 'invalid'
    with pytest.raises(ConfigError):
        load_config({'key': 0}, env_prefix='APP')
